import { SurfaceViewer } from './viewer.js';
import { DrawingLab } from './brush.js';
import { mountInkPreview } from './ink-live.js';

const token=document.querySelector('meta[name="studio-token"]').content;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={capture:'Surface Capture',atlas:'Tactile Atlas',material:'Brush & Material Lab',print:'Print Studio',gallery:'Material Gallery',dictionary:'Texture Dictionary'};
const regions=['custom','ankle','finger','fingertip','palm','nipple/areola','inner elbow','outer elbow','wrist'];
let state={},mode=location.hash.slice(1)||'capture',selectedPatch=null,selectedFrame=null,selectedMaterial=null,selectedPrint=null,selectedAtlas=null,selectedSpecimen=null;
let viewers=[],drawing=null,cameraStream=null,analysis=null,atlasHistory=[],lastAtlasSettings={},jobId=null,disposeInk=null;
const field=(label,name,value='',type='text',attrs='',hint='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${hint?`<small>${hint}</small>`:''}</label>`;
const choice=(label,name,options,value)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const check=(label,name,value=false)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const button=(label,action,extra='',primary=false)=>`<button type="button" data-action="${action}" ${extra} class="${primary?'primary':''}">${label}</button>`;
const jsonbox=(label,name,value={})=>`<label class="field"><span>${label}</span><textarea name="${name}" spellcheck="false">${esc(JSON.stringify(value,null,2))}</textarea></label>`;
const fileURL=(kind,id,file)=>`/api/files/${kind}/${id}/${file}`;
function notice(text,error=false){$('#notice').textContent=text;$('#notice').classList.toggle('error',error);}
async function api(path,method='GET',body){const response=await fetch('/api'+path,{method,headers:{'X-Studio-Token':token,...(body instanceof FormData?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));return data;}
function values(form){const out={};for(const input of form.querySelectorAll('[name]')){if(input.type==='checkbox')out[input.name]=input.checked;else if(['number','range'].includes(input.type))out[input.name]=input.value===''?null:Number(input.value);else out[input.name]=input.value;}return out;}
function advanced(form){const v=values(form);let extra={};if(v.extra)extra=JSON.parse(v.extra);delete v.extra;return {...v,...extra};}
async function refresh(renderView=true){state=await api('/state');selectedPatch=selectedPatch||state.patches.at(-1)?.id;selectedFrame=selectedFrame||state.frames.find(f=>f.kind==='rgb')?.id;selectedMaterial=selectedMaterial||state.materials.at(-1)?.id;selectedPrint=selectedPrint||state.prints.at(-1)?.id;selectedAtlas=selectedAtlas||state.atlases.at(-1)?.id;selectedSpecimen=selectedSpecimen||state.specimens.at(-1)?.id;if(renderView)await render();}
async function runJob(kind,params,onDone){
  if(jobId)throw new Error('A job is already active in this view. Wait or cancel it.');
  const job=await api('/jobs','POST',{kind,params});jobId=job.id;$('#job-panel').hidden=false;
  try{while(true){const current=await api('/jobs/'+job.id);$('#job-panel').innerHTML=`<span>${esc(current.message)}</span><progress max="1" value="${current.progress}"></progress><button id="cancel-job">Cancel</button>`;$('#cancel-job').onclick=()=>api(`/jobs/${job.id}/cancel`,'POST',{});if(current.status==='completed'){jobId=null;await refresh(false);await onDone?.(current.result);await render();notice('Completed. The new result is saved locally.');return current.result;}if(['failed','cancelled','interrupted'].includes(current.status))throw new Error(current.message);await new Promise(r=>setTimeout(r,650));}}
  finally{jobId=null;$('#job-panel').hidden=true;}
}
function patchPicker(){return choice('Source surface','patch_id',(state.patches||[]).map(p=>[p.id,p.name+(p.synthetic?' · synthetic':'')]),selectedPatch);}
function sourceStrip(){return `<div class="source-strip">${(state.patches||[]).map(p=>`<button class="source-card ${p.id===selectedPatch?'selected':''}" data-action="select-patch" data-id="${p.id}"><img loading="lazy" src="/api/patches/${p.id}/image/height" alt="${esc(p.name)} height preview"><span>${esc(p.name)}</span><small>${p.synthetic?'SYNTHETIC · ':''}${p.state.toUpperCase()} / ${p.version}</small></button>`).join('')}</div>`;}
function viewerBlock(id='surface-view'){return `<div class="viewer" id="${id}"></div><div class="viewer-status" id="${id}-status"></div><div class="viewer-controls" data-viewer-controls="${id}"><label>View<select data-option="shape"><option value="sphere">Sphere</option><option value="flat">Flat patch</option></select></label><label>Relief<select data-option="mode"><option value="combined">Split frequency</option><option value="displacement">Displacement only</option><option value="normal">Normal only</option><option value="bump">Bump only</option></select></label><label>Artistic strength<input data-option="strength" type="range" min="0" max=".5" step=".01" value=".13"></label><label><input type="checkbox" data-option="physical">Physical height on 25 mm display radius</label><label><input type="checkbox" data-option="wireframe">Wireframe</label><label><input type="checkbox" data-option="grazing">Grazing light</label><label><input type="checkbox" data-option="environment" checked>Environment</label><label>Exposure<input data-option="exposure" type="range" min=".3" max="2" step=".05" value="1"></label><label>Quality<select data-option="quality"><option value="64">Low</option><option value="128" selected>Medium</option><option value="192">High</option></select></label><label>Repeat<input data-option="repeats" type="number" min="1" max="8" value="1" style="width:54px"></label><label>Rotation<input data-option="rotation" type="range" min="0" max="360" value="0"></label></div>`;}
async function mountViewer(id,patchId=selectedPatch,materialId=null,meshData=null){
  const element=$('#'+id);if(!element)return;
  const viewer=new SurfaceViewer(element,{fallback:patchId?`/api/patches/${patchId}/image/height`:null,onStatus:t=>{const el=$('#'+id+'-status');if(el)el.textContent=t;}});viewers.push(viewer);
  if(meshData)viewer.setMesh(meshData);
  else if(materialId){const m=state.materials.find(m=>m.id===materialId);const base=fileURL('materials',materialId,'');const surface=await (await fetch(base+'surface.json')).json();viewer.setSurface(surface,{color:m.descriptor.base_color,roughness:m.descriptor.roughness});await viewer.setMaterial(base,m.descriptor);}
  else if(patchId){const surface=await api(`/patches/${patchId}/surface`);viewer.setSurface(surface);}
  const physical=$(`[data-viewer-controls="${id}"] [data-option="physical"]`);if(physical){physical.disabled=viewer.surface?.source_units!=='mm';physical.title=physical.disabled?'Requires calibrated millimeter height':'Uses calibrated height; the 25 mm radius is an authored display substrate.';}
  document.querySelectorAll(`[data-viewer-controls="${id}"] [data-option]`).forEach(input=>input.addEventListener('input',()=>{const value=input.type==='checkbox'?input.checked:['range','number'].includes(input.type)?+input.value:input.dataset.option==='quality'?+input.value:input.value;viewer.setOptions({[input.dataset.option]:value});}));
  return viewer;
}
function profileCanvas(canvas,profile){
  const ctx=canvas.getContext('2d');canvas.width=900;canvas.height=170;ctx.clearRect(0,0,900,170);const ys=profile.height.filter(v=>v!==null);if(!ys.length)return;const lo=Math.min(...ys),hi=Math.max(...ys),range=Math.max(hi-lo,1e-9);ctx.strokeStyle='#b8c3ad';ctx.beginPath();ctx.moveTo(38,140);ctx.lineTo(875,140);ctx.stroke();ctx.strokeStyle='#355b42';ctx.lineWidth=2;ctx.beginPath();let start=true;profile.height.forEach((v,i)=>{if(v===null){start=true;return;}const x=38+837*i/(profile.height.length-1),y=130-110*(v-lo)/range;if(start){ctx.moveTo(x,y);start=false;}else ctx.lineTo(x,y);});ctx.stroke();ctx.fillStyle='#66745d';ctx.font='12px Arial';ctx.fillText(`${lo.toPrecision(3)}–${hi.toPrecision(3)} ${profile.units}`,38,20);ctx.fillText(`${profile.x.at(-1).toFixed(2)} ${profile.units==='mm'?'mm':'pixels'}`,760,160);
}
async function render(){
  const workspace=$('#workspace');workspace.inert=true;workspace.setAttribute('aria-busy','true');
  document.querySelectorAll('[data-mode],#refresh,#demo').forEach(button=>button.disabled=true);
  try{
  disposeInk?.();disposeInk=null;
  viewers.forEach(v=>v.dispose());viewers=[];drawing?.dispose();drawing=null;
  if(!titles[mode])mode='capture';$('#mode-title').textContent=titles[mode];document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));
  const patch=state.patches?.find(p=>p.id===selectedPatch);$('#source-status').textContent=patch?(patch.synthetic?'Synthetic · ':'')+patch.state+(patch.units==='mm'?' · mm':' · relative relief'):'No source selected';$('#source-status').className='status '+(patch?.synthetic?'synthetic':patch?.state||'');
  await ({capture:renderCapture,atlas:renderAtlas,material:renderMaterial,print:renderPrint,gallery:renderGallery,dictionary:renderDictionary}[mode])();wireActions();
  }finally{
    workspace.inert=false;workspace.setAttribute('aria-busy','false');
    document.querySelectorAll('[data-mode],#refresh,#demo').forEach(button=>button.disabled=false);
  }
}

async function renderCapture(){
  const frame=state.frames.find(f=>f.id===selectedFrame),session=state.sessions.find(s=>s.id===frame?.session_id),patch=state.patches.find(p=>p.id===selectedPatch);
  $('#workspace').innerHTML=`<section class="mode-intro"><div><h2>From touch to a surface.</h2><p>Import a scan, inspect valid contact, then reconstruct and compare relief. Original captures stay unchanged.</p></div>${button('Open Print Studio','goto-print')}${button('Collect in dictionary','new-specimen','',true)}</section><div class="split"><div><form id="import-form" class="panel"><h3>Import a capture</h3>${choice('Input interpretation','kind',[['rgb','Tactile RGB / image sequence'],['height','Height field'],['normal','Normal map'],['mesh','Existing mesh']],'rgb')}<label class="field"><span>Images, maps, video, mesh or GelSight ZIP</span><input type="file" name="files" multiple></label><label class="field"><span>Or select an image folder</span><input type="file" name="folder" webkitdirectory multiple></label>${choice('Add to session','session_id',[['','New session'],...state.sessions.map(s=>[s.id,s.name])],'')}<details><summary>Scale, map encoding and mesh units</summary>${choice('Height units','units',['relative','mm'],'relative')}<div class="field-row">${field('X spacing (mm/px)','spacing_x','','number','step="any"')}${field('Y spacing (mm/px)','spacing_y','','number','step="any"')}</div>${field('Scale per image code','scale_per_code',1,'number','step="any"')}${field('Height bias','bias',0,'number','step="any"')}${field('Validation / scale provenance','validation_notes')}${choice('Normal convention','convention',['opengl','directx'],'opengl')}${choice('Mesh units (required if unknown)','mesh_units',[['','Choose units'],['mm','mm'],['cm','cm'],['m','m'],['inch','inch']],'')}</details><button type="submit" class="primary">Import selected files</button></form><div class="panel"><h3>Live camera</h3><p class="hint">Use a connected camera, or continue with imported data.</p><select id="camera-device" aria-label="Camera"><option value="">Default camera</option></select><div class="actions">${button('Enable camera','camera-start')}${button('Capture frame','camera-capture')}${button('Stop','camera-stop')}</div><video id="camera-preview" autoplay playsinline muted></video></div></div><div><div class="panel"><h3>Local sources</h3>${sourceStrip()}${patch?`<div class="image-grid">${[['rgb','Source appearance / height'],['mask','Valid contact'],['normal','Surface normals'],['height','Original height'],['synthetic','Synthesized pixels']].map(([k,t])=>`<figure class="image-panel"><img src="/api/patches/${patch.id}/image/${k}" alt="${t}" ${k==='height'?'id="roi-image"':''}><figcaption>${t}</figcaption></figure>`).join('')}<figure class="image-panel"><canvas id="wrinkle-overlay"></canvas><figcaption>Detected valleys after analysis</figcaption></figure></div>`:'<p class="empty">Import a height field or reconstruct a tactile frame to inspect its surface.</p>'}</div><div class="panel">${viewerBlock()}</div></div></div>
  <div class="split equal"><form id="reconstruct-form" class="panel"><h3>Reconstruct tactile RGB</h3>${choice('Frame','frame_id',state.frames.filter(f=>f.kind==='rgb').map(f=>[f.id,f.source_name]),selectedFrame)}${choice('Baseline','baseline_id',[['','No baseline'],...state.frames.filter(f=>f.session_id===session?.id&&f.kind==='rgb').map(f=>[f.id,f.source_name])],session?.baseline_id||'')}${choice('Normal calibration','calibration_id',[['','Bundled Mini model · relative only'],...state.calibrations.map(c=>[c.id,c.name+(c.validated?' · validated':' · unvalidated')])],'')}<div class="field-row">${field('Exclude border (pixels)','border',4,'number','min="0" max="100"')}${field('Marker darkness cutoff','marker_high',45,'number','min="0" max="200"')}</div>${field('Contact difference threshold','contact_threshold',8,'number','min="0" step="1"')}${field('ROI (x0,y0,x1,y1 · fractions)','roi','0,0,1,1')}<p class="hint">Drag on the original height preview to set an ROI. Without validated sensor/gel calibration, reconstruction stays relative.</p><div class="actions"><button class="primary">Reconstruct selected frame</button>${button('Save selected baseline','save-baseline')}</div>${frame?`<pre class="log">${esc(JSON.stringify(frame.quality,null,2))}</pre>`:''}</form><form id="analysis-form" class="panel"><h3>Wrinkles & cross-section</h3>${patchPicker()}<div class="field-row">${field('Detrending scale (px)','detrend',12,'number','min="0" max="150" step="1"')}${field('Smoothing (px)','smoothing',.5,'number','min="0" max="15" step=".1"')}${field('Valley sensitivity','sensitivity',.01,'number','min="0" step=".001"')}${field('Neighborhood (px)','radius_px',8,'number','min="2" max="100"')}</div>${field('Physical radius (mm, calibrated only)','radius_mm','','number','min="0" step=".01"')}${field('Profile row','profile_row',patch?Math.floor(patch.height/2):0,'number','min="0"')}<button class="primary">Analyze selected surface</button><div id="analysis-result"></div><canvas class="profile" id="profile"></canvas></form></div>
  <div class="split equal"><form id="session-form" class="panel"><h3>Capture conditions</h3>${choice('Session','id',state.sessions.map(s=>[s.id,s.name]),session?.id)}${field('Session name','name',session?.name||'')}${choice('Region label','region',regions,session?.region||'custom')}<div class="field-row">${field('Sensor ID','sensor_id',session?.sensor_id||'')}${field('Gel ID','gel_id',session?.gel_id||'')}${field('Supplied force (N)','force_n',session?.force_n??'','number','step="any"')}${field('Posture / pose notes','posture_notes',session?.posture_notes||'')}</div><button>Save capture conditions</button><p class="hint">Leave unknown values blank. Capture pressure and posture can change the imprint; this does not recover unloaded skin.</p></form><form id="calibration-form" class="panel"><h3>Sensor-specific calibration</h3><p class="hint">Use a compatible model and independent scale validation. Selecting a file is not evidence of accuracy.</p><label class="field"><span>Model weights (optional for bundled Mini)</span><input type="file" id="weights-file" accept=".bin,.npz,.pt,.pth"></label>${jsonbox('Calibration profile','profile',{name:'My calibration',sensor_id:'',gel_id:'',width:320,height:240,pixel_spacing_mm:[.05,.05],adapter:'mini_mlp',weights:'bundled_mini',validated:false,validation_notes:'',normal_convention:'image_y_down',object_sign:1})}<button>Save calibration profile</button></form></div>`;
  if(patch)await mountViewer('surface-view');
  $('#import-form').onsubmit=async e=>{e.preventDefault();await safely(async()=>{const form=e.currentTarget,v=values(form),files=[...form.elements.files.files,...form.elements.folder.files];if(!files.length)throw new Error('Select files to import.');const data=new FormData();files.forEach(f=>data.append('files',f));data.append('kind',v.kind==='mesh'?'rgb':v.kind);data.append('session_id',v.session_id);data.append('settings',JSON.stringify({units:v.units,pixel_spacing:v.spacing_x&&v.spacing_y?[v.spacing_x,v.spacing_y]:null,validation_notes:v.validation_notes,scale_per_code:v.scale_per_code,bias:v.bias,convention:v.convention,mesh_units:v.mesh_units||null}));const r=await api('/import','POST',data);const last=r.at(-1);if(last.patch)selectedPatch=last.patch.id;if(last.frame)selectedFrame=last.frame.id;await refresh();notice(`Imported ${r.length} inputs. Raw originals are preserved.`);});};
  $('#reconstruct-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget);const frame_id=v.frame_id;delete v.frame_id;v.roi=v.roi.split(',').map(Number);await runJob('reconstruct',{frame_id,settings:v},r=>selectedPatch=r.id);});};
  $('#analysis-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget);const patch_id=v.patch_id;delete v.patch_id;await runJob('analyze',{patch_id,settings:v},r=>analysis=r);});};
  $('#session-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget);for(const key of ['sensor_id','gel_id','posture_notes'])if(!v[key])v[key]=null;await api('/sessions','POST',v);await refresh();notice('Capture conditions saved.');});};
  $('#calibration-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const profile=JSON.parse(e.currentTarget.elements.profile.value),file=$('#weights-file').files[0];if(file){const data=new FormData();data.append('file',file);profile.weights=(await api('/weights','POST',data)).weights;}await api('/calibrations','POST',profile);await refresh();notice('Calibration profile saved.');});};
  $('select[name="frame_id"]').onchange=e=>{selectedFrame=e.target.value;render();};
  if(analysis&&$('#analysis-result')){const s=analysis.summary;$('#analysis-result').innerHTML=`<div class="metrics"><div class="metric"><b>${s.count}</b><span>valid valley pixels</span></div>${s.metric_depths_available&&s.p80_depth_mm!==undefined?`<div class="metric"><b>${s.median_depth_mm.toFixed(4)}</b><span>median depth · mm</span></div><div class="metric"><b>${s.p80_depth_mm.toFixed(4)}</b><span>80th percentile · mm</span></div>`:'<div class="metric"><b>Relative</b><span>Metric depth unavailable</span></div>'}</div><p class="hint">${esc(s.method)}. Masked and synthesized pixels are excluded.</p>`;profileCanvas($('#profile'),analysis.profile);const canvas=$('#wrinkle-overlay');if(canvas){canvas.width=analysis.width;canvas.height=analysis.height;const ctx=canvas.getContext('2d'),im=ctx.createImageData(canvas.width,canvas.height);for(let y=0;y<canvas.height;y++)for(let x=0;x<canvas.width;x++){let i=(y*canvas.width+x)*4;im.data[i]=analysis.valleys[y][x]?69:226;im.data[i+1]=analysis.valleys[y][x]?115:234;im.data[i+2]=analysis.valleys[y][x]?214:218;im.data[i+3]=255;}ctx.putImageData(im,0,0);}}
  const roiImage=$('#roi-image');if(roiImage){let start;roiImage.onpointerdown=e=>{const r=roiImage.getBoundingClientRect();start=[(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height];roiImage.setPointerCapture(e.pointerId);};roiImage.onpointerup=e=>{if(!start)return;const r=roiImage.getBoundingClientRect(),end=[Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];$('#reconstruct-form [name="roi"]').value=[Math.min(start[0],end[0]),Math.min(start[1],end[1]),Math.max(start[0],end[0]),Math.max(start[1],end[1])].map(v=>v.toFixed(3)).join(',');start=null;};}
}

async function renderAtlas(){
  const atlas=state.atlases.find(a=>a.id===selectedAtlas);
  $('#workspace').innerHTML=`<section class="mode-intro"><div><h2>Build a planar tactile atlas.</h2><p>Use overlapping observations of the same surface. Verified links join frames; disconnected observations remain separate islands.</p></div>${button('Export atlas','export-atlas',!atlas?'disabled':'')}</section><div class="split"><form id="atlas-form" class="panel"><h3>Ordered input frames</h3>${field('Atlas name','name','Planar tactile atlas')}${choice('Session','session',state.sessions.map(s=>[s.id,s.name]),state.frames.find(f=>f.id===selectedFrame)?.session_id||state.sessions.at(-1)?.id)}<div id="atlas-frames" class="table-wrap"></div>${check('Verify loop closures','loop_closure',true)}${check('Reconstruct relative patches before fusion','reconstruct_frames')}${check('Allow bounded affine correction','bounded_affine')}${check('Artistic local deformation (invalidates metric distances)','artistic_refine')}${field('Maximum local warp (pixels)','max_warp_px',1.5,'number','min=".1" max="3" step=".1"')}<details><summary>Manual correspondences and masks</summary><p class="hint">Point pairs are in processed frame pixels (maximum 512 on the long side). Supply at least three pairs with wide spatial coverage. Manual joins are labeled.</p>${jsonbox('Manual links','manual_links',[])}${field('Marker cutoff','marker_high',45,'number','min="0" max="180"')}${field('Border (pixels)','border',4,'number','min="0" max="50"')}</details><button class="primary">Build atlas</button><div class="actions">${button('Undo last build selection','atlas-undo')}</div></form><div>${atlas?`<div class="panel"><h3>${esc(atlas.name)}</h3><p class="hint">${esc(atlas.mode)} · ${atlas.islands.length} independent islands</p><div class="actions">${atlas.islands.map(i=>button(`Island ${i.index+1}`,'atlas-island',`data-index="${i.index}"`)).join('')}</div><div id="atlas-island"></div></div><div class="panel"><h3>Accepted and rejected links</h3><div class="table-wrap"><table><thead><tr><th>Frames</th><th>Status</th><th>Overlap</th><th>Residual</th><th>Reason</th></tr></thead><tbody>${atlas.links.map(l=>`<tr><td>${l.a+1} ↔ ${l.b+1}</td><td class="${l.accepted?'good':'bad'}">${l.accepted?l.manual?'Manual':'Accepted':'Rejected'}</td><td>${l.overlap?(l.overlap*100).toFixed(0)+'%':'—'}</td><td>${l.median_residual_px?.toFixed(2)??'—'} px</td><td>${esc(l.reason|| (l.loop_closure?'Verified loop closure':'local link'))}</td></tr>`).join('')}</tbody></table></div><p class="hint">${atlas.rejected_frames.map(f=>esc(f.reason)).join(' · ')}</p></div>`:'<div class="panel empty"><h2>Start with an overlapping sequence.</h2><p>The synthetic sample project includes a known sequence for testing. Unrelated and repetitive pairs should stay disconnected.</p></div>'}</div></div>`;
  const update=()=>{$('#atlas-frames').innerHTML=state.frames.filter(f=>f.kind==='rgb'&&f.session_id===$('#atlas-form [name="session"]').value).map(f=>`<label class="check"><input data-frame="${f.id}" type="checkbox" ${!lastAtlasSettings.exclude?.includes(f.id)?'checked':''}><img src="/api/frames/${f.id}/image" alt="" width="54" height="40" style="object-fit:contain">${esc(f.source_name)}</label>`).join('');};$('#atlas-form [name="session"]').onchange=update;update();
  $('#atlas-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget),frame_ids=[...document.querySelectorAll('[data-frame]:checked')].map(e=>e.dataset.frame);delete v.session;v.manual_links=JSON.parse(v.manual_links);atlasHistory.push({settings:lastAtlasSettings,atlasId:selectedAtlas});v.exclude=[...document.querySelectorAll('[data-frame]:not(:checked)')].map(e=>e.dataset.frame);lastAtlasSettings=v;await runJob('atlas',{frame_ids,settings:v},r=>{selectedAtlas=r.id;selectedPatch=r.islands.find(i=>i.patch_id)?.patch_id||selectedPatch;});});};
  if(atlas)showAtlasIsland(atlas,0);
}
function showAtlasIsland(atlas,index){const i=atlas.islands[index],base=fileURL('atlases',atlas.id,`island-${index}/`);$('#atlas-island').innerHTML=`<div class="viewer-controls"><label><input type="checkbox" id="footprints" checked>Frame footprints</label><label>Layer<select id="atlas-layer"><option value="appearance.png">Fused appearance</option><option value="rigid.png">Rigid baseline</option><option value="seams.png">Seams</option><option value="coverage.png">Coverage</option><option value="quality.png">Quality score</option><option value="distortion.png">Artistic distortion</option></select></label></div><canvas id="atlas-canvas" class="atlas-canvas"></canvas><p class="hint">${i.width} × ${i.height} px · graph residual ${i.graph_rms_before.toFixed(3)} → ${i.graph_rms_after.toFixed(3)} · ${i.manual?'manual layout':'verified graph'}</p>${i.patch_id?`<div class="actions">${button('Use fused relief in Material Lab','atlas-to-material',`data-id="${i.patch_id}"`)}${button('Open Print Studio','atlas-to-print',`data-id="${i.patch_id}"`)}</div>`:'<p class="private-note">Appearance-only mosaic. No height was inferred from RGB brightness. Reconstruct the source frames to fuse relief.</p>'}`;const draw=()=>{const image=new Image();image.onload=()=>{const c=$('#atlas-canvas');if(!c)return;c.width=i.width;c.height=i.height;const ctx=c.getContext('2d');ctx.drawImage(image,0,0);if($('#footprints').checked){ctx.lineWidth=Math.max(1,i.width/350);Object.entries(i.footprints).forEach(([id,pts],n)=>{ctx.strokeStyle=`hsl(${n*67},65%,50%)`;ctx.beginPath();pts.forEach(([x,y],j)=>j?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font='16px Arial';ctx.fillText(String(+id+1),pts[0][0]+7,pts[0][1]+19);});}};image.src=base+$('#atlas-layer').value;};$('#atlas-layer').onchange=draw;$('#footprints').onchange=draw;draw();wireActions();}

async function renderMaterial(){
  const material=state.materials.find(m=>m.id===selectedMaterial),patch=state.patches.find(p=>p.id===selectedPatch);
  $('#workspace').innerHTML=`<section class="mode-intro"><div><h2>A surface, many interpretations.</h2><p>Keep the source, then derive brushes, displacement and authored dielectric materials. Roughness and color are artistic choices.</p></div>${button('Export texture pack','export-textures',!material?'disabled':'',true)}${button('Open Print Studio','goto-print')}</section>${sourceStrip()}<div class="split"><div><form id="edit-form" class="panel"><h3>Non-destructive surface edit</h3>${patchPicker()}<div class="field-row">${field('Detrend (px)','detrend',0,'number','min="0" step="1"')}${field('Smoothing (px)','smoothing',0,'number','min="0" step=".1"')}${field('Height gain','height_gain',1,'number','min=".01" step=".01"')}${field('Seam band (px)','seam_band',12,'number','min="1" max="100"')}</div>${check('Make a seamless derivative','seamless')}${check('Fill missing pixels as an artistic repair','fill_gaps')}${check('Invert relief','invert')}${field('Crop x0,y0,x1,y1 (fractions)','roi','0,0,1,1')}<button>Create edited version</button><p class="hint">Original and edited versions are separate. Invented pixels are marked and excluded from measurement.</p></form><form id="material-form" class="panel"><h3>Brush & material controls</h3>${field('Material name','name',patch?.name||'New material')}<div class="field-row">${field('Color','color','#929795','color')}${field('Roughness','roughness',.62,'number','min=".02" max="1" step=".01"')}</div>${choice('Roughness model','roughness_mode',[['constant','Authored constant'],['estimated','Artistic slope estimate']],'constant')}${field('Frequency split scale (pixels)','frequency_split',3,'number','min=".1" max="64" step=".1"')}${check('Full relief in all channels (artistic override)','full_relief_override')}<details open><summary>Photoshop brush tip</summary><div class="field-row">${field('Black level','black',0,'number','min="0" max=".99" step=".01"')}${field('White level','white',1,'number','min=".01" max="1" step=".01"')}${field('Curve (gamma)','gamma',1,'number','min=".05" max="10" step=".05"')}${field('Threshold (optional)','threshold','','number','min="0" max="1" step=".01"')}${field('Edge falloff','edge_falloff',.15,'number','min="0" max="1" step=".01"')}${field('Rotation (degrees)','rotation',0,'number','step="1"')}</div>${check('Invert brush tip','tip_invert')}${field('Grain contrast','grain_contrast',1,'number','min="0" max="5" step=".1"')}<p class="hint">Black means full paint in Photoshop. Exported grain is a separate seamless derivative.</p></details><details><summary>Additional material settings</summary>${jsonbox('Advanced parameters','extra',{ior:1.45,roughness_min:.3,roughness_max:.9,roughness_scale:2})}</details><button class="primary">Generate material and brushes</button></form></div><div><div class="panel"><h3>Material preview</h3>${viewerBlock()}<p class="hint">Sphere mapping presents the sampled texture. It does not recover the original object or body shape. Repeats and preview strength are artistic.</p></div>${material?`<div class="panel"><h3>${esc(material.name)} · derived maps</h3><div class="image-grid">${['height_16.png','normal_opengl.png','roughness.png','brush_tip.png','brush_grain.png','wrinkle_mask.png'].map(name=>`<figure class="image-panel"><img src="${fileURL('materials',material.id,name)}" alt="${name}"><figcaption>${name}</figcaption></figure>`).join('')}</div><h3>Tiling preview</h3><div class="tiling" style="background-image:url('${fileURL('materials',material.id,'brush_grain.png')}')"></div></div><div class="panel"><h3>Drawing table</h3><div class="field-row three">${field('Brush size','draw_size',50,'range','min="5" max="160"')}${field('Opacity','draw_opacity',.8,'range','min="0" max="1" step=".01"')}${field('Mouse pressure','draw_pressure',.5,'range','min=".01" max="1" step=".01"')}${field('Spacing','draw_spacing',.18,'range','min=".05" max="1" step=".01"')}${field('Grain scale','draw_grainScale',1,'range','min=".25" max="5" step=".05"')}</div>${check('Artistic height-based pickup','draw_pickup')}<canvas class="drawing" id="drawing" width="1200" height="670" aria-label="Pressure-sensitive drawing canvas"></canvas><div class="actions">${button('Undo stroke','drawing-undo')}${button('Replay strokes','drawing-replay')}${button('Clear','drawing-clear')}${button('Save drawing PNG','drawing-save')}${button('Save stroke replay','drawing-strokes')}</div><p class="hint">Stylus pressure is used when available. The mouse uses the manual slider. Strokes never change source height.</p></div>`:'<div class="panel empty">Generate a material to inspect its maps and test brush strokes.</div>'}</div></div>`;
  if(patch||material)await mountViewer('surface-view',selectedPatch,material?.id);
  $('#edit-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget),patch_id=v.patch_id;delete v.patch_id;v.roi=v.roi.split(',').map(Number);await runJob('derive',{patch_id,settings:v},r=>selectedPatch=r.id);});};
  $('#material-form').onsubmit=e=>{e.preventDefault();safely(async()=>{if(!selectedPatch)throw new Error('Choose a source patch.');const v=advanced(e.currentTarget);await runJob('material',{patch_id:selectedPatch,settings:v},r=>selectedMaterial=r.id);});};
  if(material){drawing=new DrawingLab($('#drawing'),fileURL('materials',material.id,'brush_tip.png'),fileURL('materials',material.id,'brush_grain.png'));document.querySelectorAll('[name^="draw_"]').forEach(input=>input.oninput=()=>{drawing.options[input.name.slice(5)]=input.type==='checkbox'?input.checked:+input.value;});}
}

async function renderPrint(){
  const project=state.prints.find(p=>p.id===selectedPrint),patch=state.patches.find(p=>p.id===selectedPatch);
  const defaultPrinter={name:'My verified process',process:'FDM',build_volume_mm:[0,0,0],layer_height_mm:0,lateral_limit_mm:0,min_raised_line_mm:0,min_groove_mm:0,min_wall_mm:0,source_notes:''};
  $('#workspace').innerHTML=`<section class="mode-intro"><div><h2>Give the surface a physical scale.</h2><p>Preserve the source shape, enlarge its relief, and validate a closed solid before export.</p></div>${button('Export print package','export-print',!project?'disabled':'',true)}</section><div class="split"><div><form id="print-form" class="panel"><h3>Source & substrate</h3>${choice('Source type','source_kind',[['patch','Height field / atlas'],['mesh','Preserve imported mesh']],'patch')}${patchPicker()}${choice('Imported mesh','mesh_id',state.frames.filter(f=>f.kind==='mesh').map(f=>[f.id,f.source_name]),'')}${choice('Substrate','shape',[['rectangle','Rectangular relief tile'],['circle','Circular relief tile'],['curved','Curved swatch'],['sphere','Textured sphere'],['coupon','Calibration / paired coupon']],'rectangle')}${field('Project name','name',patch?.name?'Print · '+patch.name:'Relief print')}${choice('Physical scaling','scale_mode',[['uniform','Uniform enlargement'],['true','True scale'],['exaggerated','Independent XY / Z']],'uniform')}<div class="field-row">${field('XY enlargement','xy_scale',5,'number','min=".01" step=".01"')}${field('Z exaggeration','z_scale',5,'number','min=".01" step=".01"')}${field('Base thickness (mm)','base_mm',2,'number','min=".1" max="100" step=".1"')}${field('Tolerance (mm)','tolerance_mm',.03,'number','min=".00001" step="any"')}</div><details open><summary>Authored dimensions for relative sources</summary><div class="field-row">${field('Width (mm)','width_mm',50,'number','min="1" max="2000"')}${field('Height (mm)','height_mm',50,'number','min="1" max="2000"')}${field('Relief range (mm)','relief_mm',1,'number','min=".01" max="100" step=".01"')}</div>${check('Lock source aspect ratio','aspect_lock',true)}</details>${check('Inverse relief — grooves become raised lines','inverse_relief')}${choice('Missing regions','holes',[['exclude','Exclude, retaining holes and walls'],['split','Export disconnected solids separately'],['fill','Explicit derived fill']],'exclude')}${check('Accept marked synthetic / repaired pixels','accept_derived')}${field('Triangle budget','triangle_budget',120000,'number','min="2000" max="400000" step="1000"')}<details><summary>Curved shapes, labels and filtering</summary><div class="field-row">${field('Sphere radius (mm)','radius_mm',25,'number','min="1"')}${field('Curve radius (mm)','curve_radius_mm',70,'number','min="1"')}</div>${check('Add sphere display base','stand')}${field('Rectangular border (mm; 0 off)','border_mm',0,'number','min="0" max="50" step=".1"')}${field('Exterior corner radius (mm)','corner_radius_mm',0,'number','min="0" max="50" step=".1"')}${field('Label outside scan area','label')}${field('Outlier threshold (source mm; 0 off)','outlier_mm',0,'number','min="0" step=".01"')}${field('Bilateral denoise (height units; 0 off)','denoise',0,'number','min="0" step=".01"')}</details><details><summary>Paired coupon</summary>${choice('Second sample (matched dimensions / scale)','paired_id',[['','Single sample'],...state.patches.filter(p=>p.id!==selectedPatch).map(p=>[p.id,p.name])],'')}<p class="hint">Each pair uses identical XY/Z factors. Relative samples share an encoding range; differences are retained.</p></details><details><summary>Imported mesh options</summary>${choice('Explicit mesh units','mesh_units',['mm','cm','m','inch'],'mm')}${field('Uniform mesh scale','mesh_scale',1,'number','min=".001" step=".001"')}${check('Repair face orientation','repair_winding')}${check('Error-verified mesh simplification','simplify')}</details>${choice('Printer profile','printer_id',[['','No profile — process unverified'],...state.printers.map(p=>[p.id,p.name])],'')}<button class="primary">Build and validate geometry</button></form><form id="printer-form" class="panel"><h3>Printer process limits</h3><p class="hint">Enter documented or tested machine/material values. Nozzle diameter alone does not establish printable detail.</p>${jsonbox('FDM / resin printer profile','profile',defaultPrinter)}<button>Save printer profile</button></form><form id="projection-form" class="panel"><h3>Extract a mesh surface patch</h3>${choice('Imported mesh','frame_id',state.frames.filter(f=>f.kind==='mesh').map(f=>[f.id,f.source_name]),'')}${choice('Mesh units','mesh_units',['mm','cm','m','inch'],'mm')}${field('Rotation X,Y,Z (degrees; blank = fit plane)','rotation_deg','')}${field('Crop x0,y0,x1,y1','roi','0,0,1,1')}${field('Projection width (samples)','resolution',192,'number','min="16" max="512"')}<button>Project open patch</button><p class="hint">Overhangs and multiple heights are rejected. Use the mesh-preserving branch for arbitrary 3D shapes.</p></form></div><div><div class="panel"><h3>Scaled solid preview</h3>${viewerBlock('print-view')}<p class="hint">The wireframe shows actual triangles. Printable relief must exist in geometry; shader detail alone will not print.</p></div><div class="panel"><h3>Source reference</h3>${patch?`<img src="/api/patches/${patch.id}/image/height" alt="Unchanged source height" style="width:100%;max-height:220px;object-fit:contain">`:'<p class="hint">Select a source to compare it with the print.</p>'}</div>${project?printReport(project)+`<div class="panel"><h3>Actual mesh cross-section</h3><canvas id="print-section" class="profile"></canvas><p class="hint">Millimeter ruler · green: mesh intersection; rust: scaled source reference where applicable.</p></div>`:'<div class="panel empty">Choose a source and build a print to inspect dimensions, fidelity and readiness.</div>'}<div class="panel"><h3>Saved print projects</h3>${state.prints.map(p=>button(esc(p.name),'select-print',`data-id="${p.id}"`)).join(' ')}</div></div></div>`;
  if(project){try{const mesh=await(await fetch(fileURL('prints',project.id,'mesh-preview.json'))).json();await mountViewer('print-view',null,null,mesh);}catch{if(patch)await mountViewer('print-view');}}
  else if(patch)await mountViewer('print-view');
  if(project&&$('#print-section')){fetch(fileURL('prints',project.id,'cross-section.json')).then(r=>r.ok?r.json():null).then(data=>{if(data&&$('#print-section'))drawSection($('#print-section'),data);}).catch(()=>{});}
  $('#print-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget),source_id=v.source_kind==='mesh'?v.mesh_id:v.patch_id;v.printer=state.printers.find(p=>p.id===v.printer_id)||null;delete v.printer_id;delete v.patch_id;delete v.mesh_id;if(!v.paired_id)delete v.paired_id;await runJob('print',{source_id,settings:v},r=>selectedPrint=r.id);});};
  $('#printer-form').onsubmit=e=>{e.preventDefault();safely(async()=>{await api('/printers','POST',JSON.parse(e.currentTarget.elements.profile.value));await refresh();notice('Printer profile saved.');});};
  $('#projection-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget),frame_id=v.frame_id;delete v.frame_id;v.rotation_deg=v.rotation_deg?v.rotation_deg.split(',').map(Number):null;v.roi=v.roi.split(',').map(Number);await runJob('project_mesh',{frame_id,settings:v},r=>{selectedPatch=r.id;});});};
}
function printReport(p){const r=p.report;if(!r)return '<div class="panel">Project has not finished processing.</div>';return `<div class="panel"><h3>${esc(p.name)}</h3><span class="status ${r.geometry_valid?'calibrated':''}">${r.print_ready?'Ready for slicer review':r.geometry_valid?'Geometry validated · printer readiness unverified':'Needs correction'}</span><div class="metrics"><div class="metric"><b>${r.triangles.toLocaleString()}</b><span>triangles</span></div><div class="metric"><b>${r.dimensions_mm?.map(n=>n.toFixed(2)).join(' × ')||'—'}</b><span>dimensions · mm</span></div><div class="metric"><b>${r.fidelity.max_error_mm?.toFixed(5)??'—'}</b><span>maximum processing error · mm</span></div></div>${r.errors.map(e=>`<p class="bad">${esc(e)}</p>`).join('')}${r.warnings.map(e=>`<p class="hint">${esc(e)}</p>`).join('')}${r.printer_assessment.relief_layers!==undefined?`<p>${r.printer_assessment.relief_layers.toFixed(1)} layers span the relief. Estimated detail-loss fraction: ${(r.printer_assessment.estimated_lost_fraction*100).toFixed(1)}%.</p><img src="${fileURL('prints',p.id,'detail_loss.png')}" alt="Estimated detail loss at this print scale" style="width:100%;max-height:180px;object-fit:contain">`:''}<details><summary>Validation, transforms and export round trips</summary><pre class="log">${esc(JSON.stringify({checks:r.checks,fidelity:r.fidelity,transforms:p.transforms,roundtrip:p.exports.roundtrip},null,2))}</pre></details><p class="hint">Slicing: ${r.slicing}. Physical printing: ${r.physical_printing}. Digital fidelity does not measure sensor accuracy.</p></div>`;}

async function renderGallery(){
  $('#workspace').innerHTML=`<section class="mode-intro"><div><h2>A library of sampled surfaces.</h2><p>Select derived materials for a standalone sphere gallery. Raw tactile captures are excluded.</p></div>${button('Export selected gallery','export-gallery','',true)}</section><div class="grid-cards">${state.materials.length?state.materials.map(m=>`<article class="asset-card"><img loading="lazy" src="${fileURL('materials',m.id,'preview.png')}" alt="${esc(m.name)} relief preview"><div class="body"><h3>${esc(m.name)}</h3><span class="badge">${m.synthetic?'Synthetic · ':''}${esc(m.state)}</span><p>${esc(m.region)} · ${esc(m.descriptor.roughness_source)}</p><label class="check"><input type="checkbox" data-gallery="${m.id}">Include in gallery export</label><div class="actions">${button('Inspect sphere','gallery-inspect',`data-id="${m.id}"`)}${button('Print','material-print',`data-id="${m.id}"`)}${button('Collect specimen','material-specimen',`data-id="${m.id}"`)}</div></div></article>`).join(''):'<div class="empty">Generate a material in Brush & Material Lab to add it here.</div>'}</div><div id="gallery-inspector"></div>`;
}

async function renderDictionary(){
  const specimen=state.specimens.find(s=>s.id===selectedSpecimen),variant=state.impressions.find(v=>v.id===specimen?.cover_id);
  $('#workspace').innerHTML=`<section class="mode-intro"><div><h2>Texture Dictionary</h2><p>A collection of surfaces, recorded through touch. Draft specimens live here; only approved revisions enter the public build.</p></div><div class="actions">${button('Collect selected surface','new-specimen','',true)}${button('Preview all drafts','preview-dictionary')}${button('Build public collection','build-dictionary')}${button('Export exhibition','export-exhibition')}${button('Collect RGB as art','collect-frame')}</div></section><div class="source-strip">${state.specimens.map(s=>{const cover=state.impressions.find(i=>i.id===s.cover_id);return `<button data-action="select-specimen" data-id="${s.id}" class="source-card ${s.id===selectedSpecimen?'selected':''}">${cover?`<img src="${fileURL('impressions',cover.id,'thumbnail.webp')}" alt="${esc(s.title)}">`:''}<span>${esc(s.title)}</span><small>${s.state.toUpperCase()} · ${esc(s.accession)}</small></button>`;}).join('')}</div>${specimen?`<div class="specimen-editor"><div><form id="specimen-form" class="panel"><h3>Collected specimen</h3><p class="hint">${esc(specimen.accession)} · /specimens/${esc(specimen.slug)}/</p>${field('Title','title',specimen.title)}${field('Category / material','category',specimen.category)}${field('Tags (comma separated)','tags',specimen.tags.join(', '))}${choice('Body region (optional)','body_region',[['','Not applicable'],...regions],specimen.body_region||'')}${field('Common name (optional)','common_name',specimen.common_name||'')}${field('Scientific name (optional)','scientific_name',specimen.scientific_name||'')}${field('Collection date (if recorded)','collection_timestamp',specimen.collection_timestamp||'','date')}${field('Public location (only if intended)','public_location',specimen.public_location||'')}<label class="field"><span>Your collection story</span><textarea name="notes">${esc(specimen.notes)}</textarea></label>${choice('Cover impression','cover_id',state.impressions.filter(i=>i.specimen_id===specimen.id).map(i=>[i.id,`${i.created_at.slice(0,16)} · pressure ${i.settings.pressure??.55}`]),specimen.cover_id)}${choice('Material sphere','material_id',[['','No sphere'],...state.materials.map(m=>[m.id,m.name])],specimen.material_id||'')}${choice('Physical relief','print_project_id',[['','No physical relief'],...state.prints.map(p=>[p.id,p.name])],specimen.print_project_id||'')}${field('Related specimen IDs (ordered, comma separated)','related_ids',specimen.related_ids.join(', '))}${field('License','license',specimen.license)}${field('Attribution','attribution',specimen.attribution)}${choice('Fabrication status','fabrication_status',['not recorded','model only','owner reports printed'],specimen.fabrication_status)}<button class="primary">Save specimen details</button></form><form id="public-form" class="panel"><h3>Public views & downloads</h3><p class="private-note">Public images can be saved by visitors. Original body captures, sensor details and private metadata are never copied automatically.</p><h3>Views</h3>${[['impression','Cover print'],['interactive_ink','Interactive ink (sends relative relief preview)'],['surface','Source surface preview'],['material','Material sphere'],['physical_relief','Physical relief model preview']].map(([id,label])=>check(label,'view_'+id,specimen.public_assets.includes(id))).join('')}<h3>Downloads</h3>${[['print_png','High-resolution print PNG'],['transparent_png','Transparent ink mask'],['height_npy','Source height master + valid mask'],['stl','Validated STL (mm)'],['3mf','Validated 3MF'],['material_glb','Baked material GLB']].map(([id,label])=>check(label,'download_'+id,specimen.downloads.includes(id))).join('')}<button>Save public asset choices</button><div class="actions">${button('Preview exact entry','preview-entry','',true)}${button('Approve public revision','publish-entry')}${button('Unpublish','unpublish-entry')}${button('Archive','archive-entry')}</div><p class="hint">Approval selects a revision for the next website build. Publishing the website is a separate deployment. Editing a published specimen does not alter its approved snapshot until you approve an update.</p></form></div><div><div class="panel"><h3>${esc(specimen.title)} <span class="badge">${specimen.state}${specimen.synthetic?' · synthetic':''}</span></h3>${variant?`<img class="ink-preview" id="ink-preview" src="${fileURL('impressions',variant.id,'display.webp')}" alt="${esc(specimen.title)} ink impression"><p class="hint">${esc(variant.interpretation)} · source ${specimen.source_dimensions_mm?specimen.source_dimensions_mm.map(v=>v.toFixed(2)).join(' × ')+' mm':'scale unknown'} · page ${variant.print_size_mm.map(v=>v.toFixed(1)).join(' × ')} mm${variant.reproduction_magnification?' · '+variant.reproduction_magnification.toFixed(2)+'× reproduction':''}</p><div class="actions"><a class="web-link" href="${fileURL('impressions',variant.id,'print.png')}" download>Print PNG</a><a class="web-link" href="${fileURL('impressions',variant.id,'ink-transparent.png')}" download>Transparent ink</a></div>`:'<p class="empty">Generate the first impression for this specimen.</p>'}</div><form id="ink-form" class="panel"><h3>Make an impression</h3><p class="hint">Inspired by the act of recording a surface in gyotaku. This is a digital artistic interpretation, not traditional fish printing or measured ink-transfer physics.</p>${choice('Presentation','style',[['clean','Clean specimen impression'],['ink','Ink on paper'],['relief','Relief shaded']],'ink')}${field('Virtual printing pressure','pressure',variant?.settings.pressure??.55,'range','min="0" max="1" step=".01"','Higher virtual pressure includes lower parts of the surface. It is unrelated to recorded capture force.')}<div class="field-row three">${field('Contact softness','softness',.035,'number','min="0" max="1" step=".005"')}${field('Ink amount','ink_amount',.9,'number','min="0" max="1" step=".05"')}${field('Dry brush breakup','dry_brush',.12,'number','min="0" max=".95" step=".01"')}${field('Ink spread (pixels)','spread',0,'number','min="0" max="3" step=".1"')}${field('Edge softness (pixels)','edge_softness',0,'number','min="0" max="5" step=".1"')}${field('Paper grain','paper_grain',.025,'number','min="0" max=".1" step=".005"')}${field('Pigment','pigment','#293d32','color')}${field('Paper','paper','#f1e8d5','color')}${field('Rotation (degrees)','rotation',0,'number','step="1"')}</div>${check('Deliberately invert relief','invert')}<details><summary>Page size, scale and reproducibility</summary><div class="field-row">${field('Master width (pixels)','output_px',2400,'number','min="128" max="6000" step="1"')}${field('Page width (mm)','print_width_mm',150,'number','min="1" max="2000"')}${field('Margin fraction','margin',.1,'number','min="0" max=".35" step=".01"')}${field('Procedural seed','seed',7,'number','step="1"')}</div>${field('Crop x0,y0,x1,y1','crop','0,0,1,1')}${check('Show calibrated source scale bar','scale_bar')}</details><button class="primary">Save new impression variant</button><p class="hint">Every variant retains its settings and seed. Ink, paper, and breakup layers never modify the surface or print mesh.</p></form><div class="panel"><h3>Impression variants</h3><div class="image-grid">${state.impressions.filter(i=>i.specimen_id===specimen.id).map(i=>`<figure class="image-panel"><img src="${fileURL('impressions',i.id,'thumbnail.webp')}" alt="Impression variant at pressure ${i.settings.pressure}"><figcaption>${button('Use as cover','set-cover',`data-id="${i.id}"`)}</figcaption></figure>`).join('')}</div></div></div></div>`:'<div class="panel empty"><h2>Every impression starts with a specimen.</h2><p>Select a surface in Capture or Material Lab, then collect it here. One specimen can have many ink and material interpretations.</p></div>'}`;
  if(!specimen)return;
  $('#specimen-form').dataset.specimenId=specimen.id;
  disposeInk=mountInkPreview($('#ink-form'),{specimen,variant,token,fileURL,onError:t=>notice(t,true)});
  $('#specimen-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget);v.tags=v.tags.split(',').map(s=>s.trim()).filter(Boolean);v.related_ids=v.related_ids.split(',').map(s=>s.trim()).filter(Boolean);for(const key of ['body_region','common_name','scientific_name','collection_timestamp','public_location','material_id','print_project_id'])if(!v[key])v[key]=null;await api(`/specimens/${specimen.id}`,'PATCH',v);await refresh();notice('Specimen details saved; approved public revision is unchanged.');});};
  $('#public-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget);await api(`/specimens/${specimen.id}`,'PATCH',{public_assets:Object.keys(v).filter(k=>k.startsWith('view_')&&v[k]).map(k=>k.slice(5)),downloads:Object.keys(v).filter(k=>k.startsWith('download_')&&v[k]).map(k=>k.slice(9))});await refresh();notice('Public asset choices saved. Preview the exact entry before approving it.');});};
  $('#ink-form').onsubmit=e=>{e.preventDefault();safely(async()=>{const v=values(e.currentTarget);v.crop=v.crop.split(',').map(Number);await runJob('impression',{specimen_id:specimen.id,settings:v},async r=>{await api(`/specimens/${specimen.id}`,'PATCH',{cover_id:r.id});await refresh(false);});});};
}

async function safely(fn){try{await fn();}catch(error){notice(error.message,true);console.error(error);}}
function saveBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function wireActions(){document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>safely(()=>action(el.dataset.action,el.dataset)));document.querySelectorAll('select[name="patch_id"]').forEach(el=>el.onchange=()=>{selectedPatch=el.value;render();});}
async function action(name,data){
  if(name==='select-patch'){selectedPatch=data.id;selectedMaterial=null;analysis=null;return render();}
  if(name==='goto-print'){mode='print';location.hash=mode;return render();}
  if(name==='select-print'){selectedPrint=data.id;return render();}
  if(name==='new-specimen'){if(!selectedPatch)throw new Error('Select a surface patch first.');const s=await api('/specimens','POST',{source_id:selectedPatch});selectedSpecimen=s.id;mode='dictionary';location.hash=mode;return refresh();}
  if(name==='select-specimen'){selectedSpecimen=data.id;return render();}
  if(name==='set-cover'){await api(`/specimens/${selectedSpecimen}`,'PATCH',{cover_id:data.id});return refresh();}
  if(name==='preview-entry'||name==='preview-dictionary'){const ids=name==='preview-entry'?[selectedSpecimen]:state.specimens.filter(s=>s.cover_id).map(s=>s.id);const result=await runJob('dictionary_preview',{specimen_ids:ids});notice('Exact allowlisted preview prepared.');const a=document.createElement('a');a.href=result.url;a.target='_blank';a.rel='noopener';a.textContent='Open dictionary preview';a.className='web-link';$('#notice').append(' ',a);return;}
  if(name==='publish-entry'){await api(`/specimens/${selectedSpecimen}/publish`,'POST',{});await refresh();notice('Public revision approved. Build the public collection to include it in the deployment bundle.');return;}
  if(name==='unpublish-entry'||name==='archive-entry'){await api(`/specimens/${selectedSpecimen}/unpublish`,'POST',{archive:name==='archive-entry'});await refresh();notice('Entry removed from future public builds. Rebuild and deploy to update an already hosted website.');return;}
  if(name==='build-dictionary'){const r=await runJob('dictionary_build',{});notice(`Public website build contains ${r.entries} approved specimens. It is ready for deployment.`);return;}
  if(name==='export-exhibition'){const r=await runJob('exhibition_export',{});location.href='/api/downloads/'+r.id;return;}
  if(name==='collect-frame'){if(!selectedFrame)throw new Error('Select a tactile RGB frame in Capture first.');const s=await api('/specimens','POST',{source_id:selectedFrame,source_kind:'frame'});selectedSpecimen=s.id;mode='dictionary';location.hash=mode;return refresh();}
  if(name==='export-textures'){const r=await runJob('texture_export',{material_id:selectedMaterial});location.href='/api/downloads/'+r.id;return;}
  if(name==='export-print'){const r=await runJob('print_export',{id:selectedPrint});location.href='/api/downloads/'+r.id;return;}
  if(name==='export-atlas'){const r=await runJob('atlas_export',{id:selectedAtlas});location.href='/api/downloads/'+r.id;return;}
  if(name==='export-gallery'){const ids=[...document.querySelectorAll('[data-gallery]:checked')].map(e=>e.dataset.gallery);const r=await runJob('gallery_export',{material_ids:ids});location.href='/api/downloads/'+r.id;return;}
  if(name==='gallery-inspect'){selectedMaterial=data.id;$('#gallery-inspector').innerHTML=`<div class="panel" style="margin-top:22px"><h3>Material sphere</h3>${viewerBlock('gallery-view')}</div>`;await mountViewer('gallery-view',null,data.id);return;}
  if(name==='material-print'||name==='material-specimen'){const m=state.materials.find(m=>m.id===data.id);selectedPatch=m.patch_id;if(name==='material-specimen')return action('new-specimen',{});mode='print';location.hash=mode;return render();}
  if(name==='atlas-island')return showAtlasIsland(state.atlases.find(a=>a.id===selectedAtlas),+data.index);
  if(name==='atlas-to-material'||name==='atlas-to-print'){selectedPatch=data.id;mode=name==='atlas-to-material'?'material':'print';location.hash=mode;return render();}
  if(name==='atlas-undo'){const previous=atlasHistory.pop();if(previous){lastAtlasSettings=previous.settings;selectedAtlas=previous.atlasId;}return render();}
  if(name==='save-baseline'){const v=values($('#reconstruct-form')),frame=state.frames.find(f=>f.id===v.frame_id);await api('/sessions','POST',{id:frame.session_id,baseline_id:v.baseline_id||null});notice('Session baseline saved.');return refresh();}
  if(name==='camera-start'){cameraStream?.getTracks().forEach(t=>t.stop());const device=$('#camera-device').value;cameraStream=await navigator.mediaDevices.getUserMedia({video:device?{deviceId:{exact:device}}:{width:640,height:480},audio:false});$('#camera-preview').srcObject=cameraStream;const devices=await navigator.mediaDevices.enumerateDevices();$('#camera-device').innerHTML=devices.filter(d=>d.kind==='videoinput').map(d=>`<option value="${esc(d.deviceId)}">${esc(d.label||'Camera')}</option>`).join('');notice('Camera enabled. Capture a frame only when the desired surface is in contact.');return;}
  if(name==='camera-stop'){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;if($('#camera-preview'))$('#camera-preview').srcObject=null;return;}
  if(name==='camera-capture'){const video=$('#camera-preview');if(!cameraStream||!video.videoWidth)throw new Error('Enable a camera first.');const c=document.createElement('canvas');c.width=video.videoWidth;c.height=video.videoHeight;c.getContext('2d').drawImage(video,0,0);const blob=await new Promise(r=>c.toBlob(r,'image/png')),form=new FormData();form.append('files',blob,'live-'+Date.now()+'.png');form.append('kind','rgb');form.append('session_id',state.frames.find(f=>f.id===selectedFrame)?.session_id||'');const result=await api('/import','POST',form);selectedFrame=result[0].frame.id;await refresh();notice('Live frame saved locally.');return;}
  if(name==='drawing-undo')return drawing?.undo();if(name==='drawing-replay')return drawing?.replay();if(name==='drawing-clear'){drawing.strokes=[];drawing.clear();return;}
  if(name==='drawing-save')return $('#drawing').toBlob(b=>saveBlob(b,'brush-drawing.png'));
  if(name==='drawing-strokes')return saveBlob(new Blob([JSON.stringify({schema:'studio-strokes/1',material_id:selectedMaterial,strokes:drawing.strokes},null,2)],{type:'application/json'}),'brush-strokes.json');
}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(mode!==b.dataset.mode){mode=b.dataset.mode;location.hash=mode;safely(render);}});
$('#refresh').onclick=()=>safely(()=>refresh());$('#demo').onclick=()=>safely(()=>runJob('demo',{},r=>{selectedPatch=r.patches[0].id;selectedFrame=r.session.frame_ids[0];}));
window.addEventListener('hashchange',()=>{if(mode!==location.hash.slice(1)){mode=location.hash.slice(1);safely(render);}});
window.addEventListener('beforeunload',()=>{viewers.forEach(v=>v.dispose());cameraStream?.getTracks().forEach(t=>t.stop());});
await safely(()=>refresh());

function drawSection(canvas,data){
 const ctx=canvas.getContext('2d');canvas.width=900;canvas.height=240;
 const points=data.segments.flat().concat((data.source||[]).filter(Boolean));if(!points.length)return;
 const xs=points.map(p=>p[0]),zs=points.map(p=>p[1]);const loX=Math.min(...xs),hiX=Math.max(...xs),loZ=Math.min(...zs),hiZ=Math.max(...zs);
 const X=x=>45+(x-loX)/Math.max(hiX-loX,.001)*820,Z=z=>195-(z-loZ)/Math.max(hiZ-loZ,.001)*160;
 ctx.strokeStyle='#355b42';ctx.lineWidth=1.6;ctx.beginPath();for(const [a,b] of data.segments){ctx.moveTo(X(a[0]),Z(a[1]));ctx.lineTo(X(b[0]),Z(b[1]));}ctx.stroke();
 ctx.strokeStyle='#a65e38';ctx.beginPath();let pen=false;for(const p of data.source||[]){if(!p){pen=false;continue;}if(pen)ctx.lineTo(X(p[0]),Z(p[1]));else ctx.moveTo(X(p[0]),Z(p[1]));pen=true;}ctx.stroke();
 ctx.font='12px Arial';ctx.fillStyle='#46594b';for(let i=0;i<=4;i++){const x=loX+(hiX-loX)*i/4;ctx.fillText(x.toFixed(2)+' mm',X(x)-20,224);}ctx.fillText('Z '+loZ.toFixed(2)+'–'+hiZ.toFixed(2)+' mm',45,20);
}
